/** A skippable FieldShift opening sequence, with replay control in Settings. */
const copy={en:{eyebrow:'FIELD SHIFT / EARTH + LAND',title:'From Earth data<br>to a stronger field.',body:'Explore weather, water, soil, crop rotations and profit for the land you choose.',enter:'Enter FieldShift',skip:'Skip intro',replay:'Replay introduction',replayBody:'Watch the FieldShift opening sequence again.'},fr:{eyebrow:'FIELD SHIFT / TERRE + CULTURE',title:'Des données de la Terre<br>à un champ plus résilient.',body:'Explorez la météo, l’eau, le sol, les rotations et les bénéfices pour la terre choisie.',enter:'Entrer dans FieldShift',skip:'Passer l’intro',replay:'Revoir l’introduction',replayBody:'Revoir la séquence d’ouverture de FieldShift.'},ar:{eyebrow:'فيلد شيفت / الأرض + الزراعة',title:'من بيانات الأرض<br>إلى حقل أكثر صمودًا.',body:'استكشف الطقس والمياه والتربة وتناوب المحاصيل والأرباح للأرض التي تختارها.',enter:'دخول فيلد شيفت',skip:'تخطي المقدمة',replay:'إعادة المقدمة',replayBody:'شاهد تسلسل افتتاح فيلد شيفت مرة أخرى.'}};
const key='fieldshift.intro.skip-auto';
export function initIntro({language='en'}={}){
  let current=copy[language]?language:'en';
  const overlay=document.createElement('section');overlay.className='fieldshift-intro photographic';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','FieldShift introduction');
  overlay.innerHTML='<div class="intro-cinematic" aria-hidden="true"><video class="intro-film" muted playsinline preload="auto" poster="assets/intro-earth.jpg"><source media="(max-width: 600px)" src="assets/intro-zoom-mobile.mp4" type="video/mp4"><source src="assets/intro-zoom.mp4" type="video/mp4"></video></div><div class="intro-vignette" aria-hidden="true"></div><button class="intro-skip" type="button"></button><div class="intro-core"><div class="intro-mark" aria-hidden="true"><img src="assets/logo.svg" alt=""><span></span></div><span class="intro-eyebrow"></span><h1></h1><p></p><button class="intro-enter" type="button"></button><span class="intro-progress" aria-hidden="true"><i></i></span></div>';
  document.body.append(overlay);
  const apply=()=>{const words=copy[current];overlay.querySelector('.intro-eyebrow').textContent=words.eyebrow;overlay.querySelector('h1').innerHTML=words.title;overlay.querySelector('p').textContent=words.body;overlay.querySelector('.intro-enter').textContent=words.enter;overlay.querySelector('.intro-skip').textContent=words.skip;overlay.querySelector('.intro-skip').setAttribute('aria-label',words.skip);};
  const film=overlay.querySelector('.intro-film');const enter=overlay.querySelector('.intro-enter');const progress=overlay.querySelector('.intro-progress i');let revealTimer,hideTimer;
  const complete=(instant=false)=>{overlay.classList.add('story-complete');progress.style.width='100%';if(instant)enter.disabled=false;else revealTimer=setTimeout(()=>enter.disabled=false,1350);};
  film.addEventListener('ended',()=>complete());
  film.addEventListener('timeupdate',()=>{if(film.duration)progress.style.width=Math.min(100,film.currentTime/film.duration*100)+'%';});
  const close=()=>{clearTimeout(revealTimer);clearTimeout(hideTimer);film.pause();overlay.classList.add('leaving');hideTimer=setTimeout(()=>overlay.hidden=true,420);document.body.classList.remove('intro-open');document.querySelector('.topbar-field')?.focus();};
  const open=()=>{clearTimeout(revealTimer);clearTimeout(hideTimer);film.pause();film.currentTime=0;progress.style.width='0%';overlay.hidden=false;overlay.classList.remove('running','leaving','story-complete');enter.disabled=true;void overlay.offsetWidth;overlay.classList.add('running');document.body.classList.add('intro-open');overlay.querySelector('.intro-skip').focus();if(matchMedia('(prefers-reduced-motion: reduce)').matches){complete(true);return;}film.play().catch(()=>complete(true));};
  overlay.querySelector('.intro-enter').onclick=close;overlay.querySelector('.intro-skip').onclick=close;overlay.addEventListener('keydown',event=>{if(event.key==='Escape')close();});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!overlay.hidden)close();});
  const panel=document.querySelector('.settings-panel');const row=document.createElement('div');row.className='setting-item intro-replay-setting';row.innerHTML='<div><b></b><p></p></div><button type="button" class="button secondary small"></button>';panel.append(row);
  const updateRow=()=>{const words=copy[current];row.querySelector('b').textContent=words.replay;row.querySelector('p').textContent=words.replayBody;row.querySelector('button').textContent=words.replay;};row.querySelector('button').onclick=open;
  window.addEventListener('fieldshift:language',event=>{current=copy[event.detail]?event.detail:'en';apply();updateRow();});apply();updateRow();if(!sessionStorage.getItem(key))requestAnimationFrame(open);else overlay.hidden=true;return{open};
}
